async function handleGoogleDirect(modelId: string, messages: any[], env: any) {
  const apiKey = env.GOOGLE_AI_API_KEY;
  if (!apiKey) throw new Error("GOOGLE_AI_API_KEY не найден.");
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:generateContent?key=${apiKey}`;
  const contents = messages.filter(m => m.role !== 'system').map(m => ({
    role: m.role === "assistant" ? "model" : "user",
    parts: [{ text: m.content }]
  }));
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ contents })
  });
  const data: any = await res.json();
  if (!res.ok) throw new Error(data.error?.message || "Ошибка Google API");
  return data.candidates?.[0]?.content?.parts?.[0]?.text  "Нет ответа.";
}

async function handleOpenRouterDirect(modelId: string, messages: any[], env: any) {
  const apiKey = env.OPENROUTER_API_KEY;
  if (!apiKey) throw new Error("OPENROUTER_API_KEY не найден.");

  const res = await fetch("https://openrouter.ai/api/v1/chat/completions", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
      "HTTP-Referer": "https://ai.dessyatykh.workers.dev",
      "X-Title": "Shekinah Mission AI"
    },
    body: JSON.stringify({
      model: modelId,
      messages: messages,
      max_tokens: 1024
    })
  });

  const data: any = await res.json();
  if (!res.ok) throw new Error(data.error?.message  "Ошибка OpenRouter API");
  return data.choices?.[0]?.message?.content || "Нет ответа от OpenRouter.";
}

