    if (!update.message || !update.message.text) {
      // Игнорируем нетекстовые обновления
      return new Response(JSON.stringify({ ok: true }), { status: 200 });
    }

    const chatId = update.message.chat.id;
    const userMessage = update.message.text;

    // Эмуляция запроса для handleChatRequestLogic
    const syntheticRequestData = {
      messages: [{ role: "user", content: userMessage }],
      model: DEFAULT_MODEL_KEY,
    };

    // Вызываем вашу основную логику AI
    const result = await handleChatRequestLogic(syntheticRequestData, env);

    // Отправляем ответ обратно в Telegram
    const botToken = env.TELEGRAM_BOT_TOKEN;
    if (!botToken) throw new Error("TELEGRAM_BOT_TOKEN не установлен в env.");

    const apiUrl = `${TELEGRAM_API_URL}${botToken}/sendMessage`;

    const telegramPayload = {
      chat_id: chatId,
      text: result.response,
      parse_mode: "Markdown",
    };

    await fetch(apiUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(telegramPayload),
    });

    // Всегда отвечаем Telegram'у 200 OK
