async function handleChatRequestLogic(requestData: any, env: any) {
    const messages: any[] = Array.isArray(requestData.messages) ? requestData.messages : [];
    const modelKey = requestData.model || DEFAULT_MODEL_KEY;
    const modelId = SUPPORTED_MODELS[modelKey] || SUPPORTED_MODELS[DEFAULT_MODEL_KEY];
    const fileContents = requestData.fileContents;

    let chatMessages: any[] = [...messages];

    if (fileContents) {
      chatMessages.unshift({ role: "system", content: `Содержимое загруженных файлов:\n${fileContents}` });
    }

    if (!chatMessages.some((msg) => msg.role === "system")) {
      const systemPrompt = SYSTEM_PROMPT_TEMPLATE.replace("{MODEL_NAME}", modelKey);
